const aiResponse = $input.first().json.message.content;

// Find the JSON block even if there is text before/after it
const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);

if (jsonMatch) {
  try {
    return { json: JSON.parse(jsonMatch[0]) };
  } catch (e) {
    return { json: { error: "Invalid JSON format", raw: aiResponse } };
  }
}
return { json: { error: "No JSON found", raw: aiResponse } };
